import React, { useEffect, useMemo, useState } from "react";
import api from "../services/api.ts";
import { API_ENDPOINTS, crestUrl } from "../config/urls.ts";
import { describeApiError } from "../utils/apiError.ts";
import { Crest } from "./ui.tsx";

interface PlayerRow {
  playerId: number;
  playerName: string;
  proName?: string;
  clubId: number;
  totalGoals: number;
  totalAssists: number;
}

interface GoalLinkingSectionProps {
  matchId: string;
  clubId: number;
  clubName: string;
  clubCrestAssetId?: string | null;
  players: PlayerRow[];
  /** Vínculos já gravados (GET /api/Matches/{id}/goals) — buscados uma única vez pela página */
  goalsData: ApiGoalsResponse | null;
  goalsLoading: boolean;
  goalsError: string | null;
}

interface GoalLink {
  scorerPlayerId: number;
  goalIndex: number;
  assistPlayerId: number | null;
  preAssistPlayerId: number | null;
  // Names from API (for read-only display)
  scorerName?: string;
  assistName?: string;
  preAssistName?: string;
}

export interface ApiGoal {
  matchGoalLinkId: number;
  matchId: number;
  clubId: number;
  scorerPlayerEntityId: number;
  scorerName: string;
  assistPlayerEntityId: number | null;
  assistName: string | null;
  preAssistPlayerEntityId: number | null;
  preAssistName: string | null;
}

export interface ApiGoalsResponse {
  matchId: number;
  totalGoals: number;
  goals: ApiGoal[];
}

export function GoalLinkingSection({
  matchId,
  clubId,
  clubName,
  clubCrestAssetId,
  players,
  goalsData,
  goalsLoading,
  goalsError,
}: GoalLinkingSectionProps) {
  const [goalLinks, setGoalLinks] = useState<GoalLink[]>([]);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const loading = goalsLoading;
  const error = saveError ?? goalsError;

  // Helper to get display name (proName with fallback to playerName)
  const getDisplayName = (player: PlayerRow): string => {
    return player.proName || player.playerName;
  };

  const getPlayerDisplayName = (playerId: number | null): string => {
    if (playerId === null) return "-";
    const player = players.find((p) => p.playerId === playerId);
    if (!player) return "-";
    return getDisplayName(player);
  };

  const playersKey = players.map((p) => `${p.playerId}:${p.totalGoals}`).join(",");

  // Generate goal rows from players with goals
  const initialGoalLinks = useMemo(() => {
    const rows: GoalLink[] = [];
    const scorers = players.filter((p) => p.totalGoals > 0);

    scorers.forEach((player) => {
      for (let i = 0; i < player.totalGoals; i++) {
        rows.push({
          scorerPlayerId: player.playerId,
          goalIndex: i + 1,
          assistPlayerId: null,
          preAssistPlayerId: null,
        });
      }
    });

    return rows;
    // chave por conteúdo: a página repassa um array novo a cada render e isso não pode refazer a carga
  }, [playersKey]);

  // Inicializa a partir dos vínculos gravados (ou, na falta deles, das estatísticas dos jogadores)
  useEffect(() => {
    if (goalsLoading) return;
    if (goalsError || !goalsData) {
      // Falha de leitura não significa que não existam vínculos gravados.
      setGoalLinks([]);
      return;
    }
    setSaveError(null);

    // Filter goals for this club only (use Number() to ensure type match)
    const numericClubId = Number(clubId);
    const clubGoals = goalsData.goals.filter((g) => Number(g.clubId) === numericClubId);

    if (clubGoals.length > 0) {
      const existingLinks: GoalLink[] = clubGoals.map((g, index) => ({
        scorerPlayerId: g.scorerPlayerEntityId,
        goalIndex: index + 1,
        assistPlayerId: g.assistPlayerEntityId,
        preAssistPlayerId: g.preAssistPlayerEntityId,
        scorerName: g.scorerName,
        assistName: g.assistName ?? undefined,
        preAssistName: g.preAssistName ?? undefined,
      }));
      setGoalLinks(existingLinks);
      setSaved(true);
    } else {
      // No existing data, use initial links from player stats
      setGoalLinks(initialGoalLinks);
      setSaved(false);
    }
  }, [goalsData, goalsLoading, goalsError, clubId, initialGoalLinks]);

  // Players with at least one assist (base list, will be filtered per row)
  const playersWithAssists = useMemo(
    () => players.filter((p) => p.totalAssists > 0),
    [players]
  );

  // Count how many times each player has been assigned as assist
  const usedAssistCounts = useMemo(() => {
    const counts = new Map<number, number>();
    goalLinks.forEach((g) => {
      if (g.assistPlayerId !== null) {
        counts.set(g.assistPlayerId, (counts.get(g.assistPlayerId) ?? 0) + 1);
      }
    });
    return counts;
  }, [goalLinks]);

  // Get eligible assist candidates for a specific goal
  // - Excludes scorer
  // - Excludes players who have used all their available assists (unless they're the current selection)
  const getAssistCandidates = (goal: GoalLink): PlayerRow[] => {
    return playersWithAssists.filter((p) => {
      // Can't assist your own goal
      if (p.playerId === goal.scorerPlayerId) return false;

      // Always show the currently selected player
      if (p.playerId === goal.assistPlayerId) return true;

      // Check if player still has assists available
      const usedCount = usedAssistCounts.get(p.playerId) ?? 0;
      return usedCount < p.totalAssists;
    });
  };

  // Get eligible pre-assist candidates for a specific goal (excludes scorer and assist)
  const getPreAssistCandidates = (goal: GoalLink): PlayerRow[] => {
    return players.filter(
      (p) => p.playerId !== goal.scorerPlayerId && p.playerId !== goal.assistPlayerId
    );
  };

  const handleAssistChange = (index: number, playerId: number | null) => {
    setGoalLinks((prev) =>
      prev.map((g, i) => {
        if (i !== index) return g;
        // Clear pre-assist if assist is cleared OR if new assist equals current pre-assist
        const shouldClearPreAssist =
          playerId === null || playerId === g.preAssistPlayerId;
        return {
          ...g,
          assistPlayerId: playerId,
          preAssistPlayerId: shouldClearPreAssist ? null : g.preAssistPlayerId,
        };
      })
    );
  };

  const handlePreAssistChange = (index: number, playerId: number | null) => {
    setGoalLinks((prev) =>
      prev.map((g, i) => (i === index ? { ...g, preAssistPlayerId: playerId } : g))
    );
  };

  const handleSubmit = async () => {
    // Vínculo manual de gols é PÚBLICO (sem login; o backend limita por IP e devolve 429 quando excede)
    setSaving(true);
    setSaveError(null);
    try {
      await api.post(API_ENDPOINTS.MATCH_GOALS(matchId), {
        goals: goalLinks.map((g) => ({
          scorerPlayerEntityId: g.scorerPlayerId,
          assistPlayerEntityId: g.assistPlayerId,
          preAssistPlayerEntityId: g.preAssistPlayerId,
        })),
      });
      setSaved(true);
    } catch (err: any) {
      setSaveError(describeApiError(err, "Erro ao salvar vínculos").message);
    } finally {
      setSaving(false);
    }
  };

  // Check if there are multiple goals by the same player
  const hasMultipleGoals = useMemo(() => {
    const goalsPerPlayer = new Map<number, number>();
    players.forEach((p) => {
      if (p.totalGoals > 0) {
        goalsPerPlayer.set(p.playerId, p.totalGoals);
      }
    });
    return Array.from(goalsPerPlayer.values()).some((count) => count > 1);
  }, [players]);

  const formatScorerName = (goal: GoalLink) => {
    // Use API name if available (read-only mode), otherwise lookup from players
    const player = players.find((p) => p.playerId === goal.scorerPlayerId);
    const name = goal.scorerName || (player ? getDisplayName(player) : "Desconhecido");

    if (hasMultipleGoals) {
      const playerGoals = player?.totalGoals ?? 1;
      if (playerGoals > 1) {
        return `${name} (${goal.goalIndex})`;
      }
    }
    return name;
  };

  // Get display name for assist/pre-assist (uses API name if available)
  const getAssistDisplayName = (goal: GoalLink, type: "assist" | "preAssist"): string => {
    if (type === "assist") {
      if (goal.assistName) return goal.assistName;
      return getPlayerDisplayName(goal.assistPlayerId);
    } else {
      if (goal.preAssistName) return goal.preAssistName;
      return getPlayerDisplayName(goal.preAssistPlayerId);
    }
  };

  // Loading state
  if (loading) {
    return (
      <div className="bg-surface shadow-sm rounded-xl p-4 border">
        <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
          <Crest src={crestUrl(clubCrestAssetId)} alt={`Escudo ${clubName}`} size={24} rounded="rounded-full" />
          {clubName} - Assistências
        </h3>
        <p className="text-sm text-fg-muted">Carregando...</p>
      </div>
    );
  }

  // No goals case
  if (error && goalLinks.length === 0) {
    return (
      <div className="bg-surface shadow-sm rounded-xl p-4 border">
        <h3 className="text-lg font-semibold mb-4">{clubName} - Assistências</h3>
        <p role="alert" className="text-sm text-negative-fg">{error}</p>
      </div>
    );
  }

  if (goalLinks.length === 0) {
    return (
      <div className="bg-surface shadow-sm rounded-xl p-4 border">
        <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
          <Crest src={crestUrl(clubCrestAssetId)} alt={`Escudo ${clubName}`} size={24} rounded="rounded-full" />
          {clubName} - Vincular Assistências
        </h3>
        <p className="text-sm text-fg-muted">Nenhum gol marcado nesta partida.</p>
      </div>
    );
  }

  return (
    <div className="bg-surface shadow-sm rounded-xl p-4 border">
      <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
        <Crest src={crestUrl(clubCrestAssetId)} alt={`Escudo ${clubName}`} size={24} rounded="rounded-full" />
        {clubName} - {saved ? "Assistências Vinculadas" : "Vincular Assistências"}
      </h3>

      {error && (
        <div className="mb-4 p-3 text-sm text-negative-fg bg-negative-soft border border-negative/30 rounded">
          {error}
        </div>
      )}

      <div className="overflow-x-auto">
        <table className="w-full table-auto text-sm border">
          <thead>
            <tr className="bg-surface-raised">
              <th scope="col" className="p-2 text-left font-medium">Gol</th>
              <th scope="col" className="p-2 text-center text-fg-subtle w-8"><span className="sr-only">assistido por</span></th>
              <th scope="col" className="p-2 text-left font-medium">Assistência</th>
              <th scope="col" className="p-2 text-center text-fg-subtle w-8"><span className="sr-only">pré-assistido por</span></th>
              <th scope="col" className="p-2 text-left font-medium">Pré-Assistência</th>
            </tr>
          </thead>
          <tbody>
            {goalLinks.map((goal, index) => {
              const assistCandidates = getAssistCandidates(goal);
              const preAssistCandidates = getPreAssistCandidates(goal);

              return (
                <tr key={`${goal.scorerPlayerId}-${goal.goalIndex}`} className="border-t">
                  <td className="p-2 font-medium">{formatScorerName(goal)}</td>
                  <td className="p-2 text-center text-fg-subtle">←</td>
                  <td className="p-2">
                    {saved ? (
                      <span>{getAssistDisplayName(goal, "assist")}</span>
                    ) : (
                      <select
                        aria-label={`Assistência do gol de ${formatScorerName(goal)}`}
                        value={goal.assistPlayerId ?? ""}
                        onChange={(e) =>
                          handleAssistChange(
                            index,
                            e.target.value ? Number(e.target.value) : null
                          )
                        }
                        className="border rounded px-2 py-1 text-sm w-full max-w-[200px]"
                      >
                        <option value="">Selecionar...</option>
                        {assistCandidates.map((p) => (
                          <option key={p.playerId} value={p.playerId}>
                            {getDisplayName(p)}
                          </option>
                        ))}
                      </select>
                    )}
                  </td>
                  <td className="p-2 text-center text-fg-subtle">←</td>
                  <td className="p-2">
                    {saved ? (
                      <span>{getAssistDisplayName(goal, "preAssist")}</span>
                    ) : (
                      <select
                        aria-label={`Pré-assistência do gol de ${formatScorerName(goal)}`}
                        value={goal.preAssistPlayerId ?? ""}
                        onChange={(e) =>
                          handlePreAssistChange(
                            index,
                            e.target.value ? Number(e.target.value) : null
                          )
                        }
                        disabled={goal.assistPlayerId === null}
                        className="border rounded px-2 py-1 text-sm w-full max-w-[200px] disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        <option value="">Selecionar...</option>
                        {preAssistCandidates.map((p) => (
                          <option key={p.playerId} value={p.playerId}>
                            {getDisplayName(p)}
                          </option>
                        ))}
                      </select>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {!saved && (
        <div className="mt-4 flex justify-end">
          <button
            onClick={handleSubmit}
            disabled={saving}
            className="inline-flex items-center gap-2 rounded-lg border border-accent px-4 py-2 text-sm font-medium shadow-sm bg-accent text-accent-fg hover:brightness-110 disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {saving ? "Salvando..." : "Salvar Vínculos"}
          </button>
        </div>
      )}
    </div>
  );
}
